      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class PerformanceGPUManager : MonoBehaviour
{
    [Header("Configuracoes de Qualidade GPU")]
    [SerializeField] private float dynamicResolutionFactor = 0.85f;
    [SerializeField] private int targetFrameRate = 60;

    private void Awake()
    {
        Application.targetFrameRate = targetFrameRate;
        QualitySettings.vSyncCount = 0;

        // Reduz a resolucao de renderizacao interna para aliviar a GPU
        ScalableBufferManager.ResizeBuffers(dynamicResolutionFactor, dynamicResolutionFactor);

        // Otimizacoes basicas de pipeline
        QualitySettings.shadowDistance = Mathf.Min(QualitySettings.shadowDistance, 40f);
        QualitySettings.shadowCascades = 2;
    }

    public void SetDynamicResolution(float scale)
    {
        scale = Mathf.Clamp(scale, 0.5f, 1.0f);
        ScalableBufferManager.ResizeBuffers(scale, scale);
    }
}",
      "explicacao_didatica": "A placa de video (GPU) esta demorando o dobro do tempo maximo permitido (32.76ms contra 16.7ms necessarios para 60 FPS). Isso ocorre quando a tela precisa desenhar muitos pixels repetidos (overdraw), aplicar efeitos de pos-processamento pesados ou calcular sombras muito detalhadas. O script reduz a resolucao interna de renderizacao e limita a distancia das sombras, diminuindo drasticamente a quantidade de trabalho que a placa de video realiza por frame."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Alocacoes transientes de memoria causando picos de Garbage Collector de 5.58ms (ate 98KB alocados por ciclo), gerando microtravamentos (stutters) no frame.",
      "codigo_refatorado": "using UnityEngine;
using System.Collections.Generic;

public class NonAllocObjectPool : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int initialCapacity = 64;

    private readonly Queue<GameObject> poolQueue = new Queue<GameObject>();

    private void Awake()
    {
        for (int i = 0; i < initialCapacity; i++)
        {
            GameObject obj = Instantiate(prefab, transform);
            obj.SetActive(false);
            poolQueue.Enqueue(obj);
        }
    }

    public GameObject Get()
    {
        if (poolQueue.Count > 0)
        {
            GameObject obj = poolQueue.Dequeue();
            obj.SetActive(true);
            return obj;
        }
        return Instantiate(prefab);
    }

    public void ReturnToPool(GameObject obj)
    {
        obj.SetActive(false);
        obj.transform.SetParent(transform);
        poolQueue.Enqueue(obj);
    }
}",
      "explicacao_didatica": "Criar e destruir objetos via Instantiate e Destroy, alem de concatenar texto ou criar novas listas a cada frame, gera 'lixo' na memoria RAM. Quando a memoria enche, o Garbage Collector pausa o jogo inteiro por 5.58ms para fazer a limpeza. O script usa 'Object Pooling' (reutilizacao de objetos), mantendo objetos prontos na memoria para nunca precisar cria-los nem descarta-los repetidamente."
    }
  ],
  "dicas_level_design": "O limite de Draw Calls foi violado (pico de 2797 contra o teto de 2579). Recomendacoes para Level Design e Assets: (1) Oclusao de Cenario: Configure e asse o Occlusion Culling (Window > Rendering > Occlusion Culling) para impedir o envio de objetos escondidos atras de paredes para a GPU. (2) Batching Estatico: Marque cenarios e estruturas imoveis como 'Batching Static' e utilize materiais compartilhados sempre que possivel. (3) GPU Instancing: Nos materiais de vegetacao, detritos e pedras repetidas, marque a caixa 'Enable GPU Instancing'. (4) Texture Atlasing: Agrupe texturas de multiplos objetos menores em um unico atlas para reduzir a troca de materiais. (5) LOD Groups: Implemente sistemas de LOD (Level of Detail) em objetos complexos para simplificar a geometria e desligar renderers a media e longa distancia."
}

